?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Smart Search - <?=e(setting('site_name','ShahkotPK'))?></title><link rel="stylesheet" href="/assets/platform-v4.0.0.css?v=430"><link rel="stylesheet" href="/assets/ai-v4.3.0.css?v=430"></head><body class="v4-public ai43-public"><header class="v4-public-head"><a href="/">← ShahkotPK</a><b>AI Smart Search</b><a href="/shop.php">Shop</a></header><main class="v4-public-shell"><section class="v4-search-hero ai43-hero"><span>LOCAL-FIRST INTENT SEARCH · v4.3</span><h1>Ask naturally. ShahkotPK understands intent, budget and type.</h1><p>Try “used phone under 50k”, “property for rent”, “best dentist”, “digital product” or “jobs near Shahkot”.</p><form><input name="q" value="<?=e($q)?>" placeholder="What are you looking for?" required><button>Smart Search</button></form><?php if($q!==''&&$intent):?><div class="ai43-intent"><?php foreach(array_slice($intent['keywords']??[],0,6) as $x):?><span><?=e($x)?></span><?php endforeach;?><?php if(!empty($intent['product_type'])):?><span><?=e($intent['product_type'])?> product</span><?php endif;?><?php if(!empty($intent['budget']['max'])):?><span>≤ Rs <?=e(number_format((float)$intent['budget']['max']))?></span><?php endif;?><?php if(!empty($intent['budget']['min'])):?><span>≥ Rs <?=e(number_format((float)$intent['budget']['min']))?></span><?php endif;?></div><?php endif;?></section><?php if($q!==''):?><div class="v4-result-head"><h2>Results for “<?=e($q)?>”</h2><span><?=e((int)($results['meta']['count']??(count($results['businesses'])+count($results['products'])+count($results['city_content']))))?> matches · <?=e((int)($results['meta']['duration_ms']??0))?> ms</span></div><section class="v4-results"><div><h3>Businesses</h3><?php foreach($results['businesses'] as $r):?><a href="/business.php?slug=<?=urlencode($r['slug'])?>"><b><?=e($r['name'])?></b><span><?=e($r['category_name'].' · '.$r['city_name'])?></span></a><